package com.primehr.rewardsrecognition.application;

import com.fasterxml.jackson.databind.ObjectMapper;import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.rewardsrecognition.api.RrEvaluationDtos.*;import com.primehr.rewardsrecognition.domain.*;import com.primehr.rewardsrecognition.infrastructure.*;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;

@Service @Transactional
public class RrEvaluationServiceImpl implements RrEvaluationService{
 private static final ZoneId MANILA=ZoneId.of("Asia/Manila");private final RrEvaluationCaseRepository cases;private final RrEligibilityFindingRepository findings;private final RrEvaluatorAssignmentRepository assignments;private final RrCriterionRatingRepository ratings;private final RrDecisionEventRepository events;private final RrDecisionIssueRepository issues;private final RrNominationRepository nominations;private final RrNominationMemberRepository nominationMembers;private final RrAwardCycleRepository cycles;private final RrAwardCategoryVersionRepository categories;private final RrAwardCriterionRepository criteria;private final RrCommitteeCharterVersionRepository charters;private final RrCommitteeMemberRepository committeeMembers;private final PrimeHrAuditService audit;private final ObjectMapper json;
 public RrEvaluationServiceImpl(RrEvaluationCaseRepository cases,RrEligibilityFindingRepository findings,RrEvaluatorAssignmentRepository assignments,RrCriterionRatingRepository ratings,RrDecisionEventRepository events,RrDecisionIssueRepository issues,RrNominationRepository nominations,RrNominationMemberRepository nominationMembers,RrAwardCycleRepository cycles,RrAwardCategoryVersionRepository categories,RrAwardCriterionRepository criteria,RrCommitteeCharterVersionRepository charters,RrCommitteeMemberRepository committeeMembers,PrimeHrAuditService audit,ObjectMapper json){this.cases=cases;this.findings=findings;this.assignments=assignments;this.ratings=ratings;this.events=events;this.issues=issues;this.nominations=nominations;this.nominationMembers=nominationMembers;this.cycles=cycles;this.categories=categories;this.criteria=criteria;this.charters=charters;this.committeeMembers=committeeMembers;this.audit=audit;this.json=json;}
 @Override @Transactional(readOnly=true)public List<CaseResponse>cases(String a,String actor,PermissionDataScope scope){return cases.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(x->visible(a,x,actor,scope)).map(x->response(a,x)).toList();}
 @Override @Transactional(readOnly=true)public CaseResponse get(String a,String id,String actor,PermissionDataScope scope){var x=entity(a,id);access(a,x,actor,scope);return response(a,x);}
 @Override public CaseResponse initialize(String a,String nominationId,InitializeInput in,String actor,String c){var n=nomination(a,nominationId);check(n.getVersion(),in.nominationRecordVersion());if(n.getStatus()!=RrNomination.Status.SUBMITTED)throw new IllegalStateException("Only a submitted nomination may enter eligibility review");if(cases.findByAgencyIdAndNominationId(a,n.getId()).isPresent())throw new OptimisticConflictException("An evaluation case already exists for this nomination");var cycle=cycles.findByIdAndAgencyId(n.getCycleId(),a).orElseThrow(()->new ResourceNotFoundException("Award cycle not found"));LocalDate today=LocalDate.now(MANILA);if(today.isBefore(cycle.getEvaluationOpensOn())||today.isAfter(cycle.getEvaluationClosesOn()))throw new IllegalStateException("Award cycle is outside its evaluation window");var charter=charters.findByIdAndAgencyId(in.charterVersionId(),a).orElseThrow(()->new ResourceNotFoundException("Committee charter version not found"));if(!charter.effectiveOn(today))throw new IllegalStateException("Committee charter is not published and effective");var roster=committeeMembers.findByAgencyIdAndCharterVersionIdOrderByMemberRoleAscDisplayNameAsc(a,charter.getId()).stream().filter(m->!today.isBefore(m.getEffectiveFrom())&&(m.getEffectiveTo()==null||!today.isAfter(m.getEffectiveTo()))).toList();if(roster.stream().noneMatch(RrCommitteeMember::isVotingMember))throw new IllegalStateException("The frozen committee roster has no voting member");var value=cases.saveAndFlush(new RrEvaluationCase(a,n.getId(),n.getCycleId(),n.getCategoryVersionId(),charter.getId(),charter.getDefinitionVersion(),fingerprint(charter,roster)));List<RrEvaluatorAssignment> rows=new ArrayList<>();for(var m:roster){var row=new RrEvaluatorAssignment(a,value.getId(),m);if(isNominee(a,n,m.getEmployeeNo()))row.conflict("Evaluator is the nominee or a member of the nominated group");rows.add(row);}assignments.saveAllAndFlush(rows);record(a,"CREATE_RR_EVALUATION_CASE",value,null,response(a,value),null,c);return response(a,value);}
 @Override public CaseResponse eligibility(String a,String id,EligibilityInput in,String actor,String c){var value=entity(a,id);check(value.getVersion(),in.recordVersion());boolean failed=in.findings().stream().anyMatch(x->x.outcome()==RrEligibilityFinding.Outcome.FAIL);if(in.decision()==RrEvaluationCase.Status.ELIGIBLE&&failed)throw new IllegalArgumentException("A nomination with a failed eligibility finding cannot be marked eligible");if(in.decision()==RrEvaluationCase.Status.DISQUALIFIED&&!failed)throw new IllegalArgumentException("Disqualification requires at least one failed eligibility finding");var before=response(a,value);findings.deleteByAgencyIdAndEvaluationCaseId(a,id);findings.saveAll(in.findings().stream().map(x->new RrEligibilityFinding(a,id,x.ruleCode(),x.ruleLabel(),x.outcome(),x.rationale())).toList());value.decideEligibility(in.decision(),in.summary(),actor,Instant.now());if(in.decision()==RrEvaluationCase.Status.ELIGIBLE)value.beginEvaluation();value=cases.saveAndFlush(value);record(a,"DECIDE_RR_ELIGIBILITY",value,before,response(a,value),in.summary(),c);return response(a,value);}
 @Override public CaseResponse conflict(String a,String caseId,String assignmentId,ConflictInput in,String actor,PermissionDataScope scope,String c){var value=entity(a,caseId);var assignment=assignment(a,assignmentId);belong(value,assignment);if(!assignment.getEmployeeNo().equalsIgnoreCase(actor)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the evaluator or Agency Wide authority may declare this conflict");check(assignment.getVersion(),in.recordVersion());assignment.conflict(in.reason());assignments.saveAndFlush(assignment);record(a,"DECLARE_RR_EVALUATOR_CONFLICT",assignment,null,Map.of("reason",in.reason()),in.reason(),c);return response(a,value);}
 @Override public CaseResponse replace(String a,String caseId,String assignmentId,ReplacementInput in,String actor,String c){var value=entity(a,caseId);var recused=assignment(a,assignmentId);var replacement=assignment(a,in.replacementAssignmentId());belong(value,recused);belong(value,replacement);check(recused.getVersion(),in.recusedRecordVersion());if(replacement.getStatus()!=RrEvaluatorAssignment.Status.ASSIGNED||replacement.isConflictDeclared())throw new IllegalStateException("Replacement must be an active non-conflicted frozen committee member");recused.replaceWith(replacement.getId());assignments.saveAndFlush(recused);record(a,"REPLACE_RR_RECUSED_EVALUATOR",recused,null,Map.of("replacementAssignmentId",replacement.getId()),"Authorized frozen-roster replacement",c);return response(a,value);}
 @Override public CaseResponse score(String a,String caseId,String assignmentId,ScoreInput in,String actor,String c){var value=entity(a,caseId);if(value.getStatus()!=RrEvaluationCase.Status.EVALUATION)throw new IllegalStateException("Case is not open for independent evaluation");var assignment=assignment(a,assignmentId);belong(value,assignment);if(!assignment.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Evaluator scores are member-owned until submitted");check(assignment.getVersion(),in.recordVersion());var configured=criteria.findByAgencyIdAndCategoryVersionIdOrderByDisplayOrderAsc(a,value.getCategoryVersionId());if(configured.isEmpty())throw new IllegalStateException("Award category has no criteria");Map<String,RatingInput> supplied=new HashMap<>();for(var x:in.ratings())if(supplied.put(x.criterionId(),x)!=null)throw new IllegalArgumentException("Criterion ratings must be unique");if(supplied.size()!=configured.size()||configured.stream().anyMatch(x->!supplied.containsKey(x.getId())))throw new IllegalArgumentException("Every frozen award criterion must be rated exactly once");ratings.deleteByAgencyIdAndAssignmentId(a,assignment.getId());var rows=configured.stream().map(x->{var s=supplied.get(x.getId());return new RrCriterionRating(a,assignment.getId(),x,s.score(),s.comments());}).toList();ratings.saveAllAndFlush(rows);BigDecimal total=rows.stream().map(RrCriterionRating::getWeightedScore).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(4,RoundingMode.HALF_UP);assignment.submit(total,in.attending(),Instant.now());assignments.saveAndFlush(assignment);record(a,"SUBMIT_RR_INDEPENDENT_EVALUATION",assignment,null,Map.of("calculatedScore",total),null,c);return response(a,value);}
 @Override public CaseResponse recommend(String a,String id,RecommendationInput in,String actor,String c){var value=entity(a,id);check(value.getVersion(),in.recordVersion());if(value.getStatus()==RrEvaluationCase.Status.EVALUATION){var submitted=activeSubmitted(a,id);if(submitted.isEmpty())throw new IllegalStateException("No independent evaluator submission is available");BigDecimal avg=submitted.stream().map(RrEvaluatorAssignment::getTotalScore).reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(submitted.size()),4,RoundingMode.HALF_UP);value.beginDeliberation(avg);}var charter=charters.findByIdAndAgencyId(value.getCharterVersionId(),a).orElseThrow(()->new ResourceNotFoundException("Committee charter not found"));var all=assignments.findByAgencyIdAndEvaluationCaseIdOrderByDisplayName(a,id);int eligible=(int)all.stream().filter(x->x.isVotingMember()&&!x.isConflictDeclared()&&x.getStatus()!=RrEvaluatorAssignment.Status.REPLACED).count();int attending=(int)all.stream().filter(x->x.isVotingMember()&&x.getStatus()==RrEvaluatorAssignment.Status.SUBMITTED&&x.isAttending()).count();boolean quorum=charter.getQuorumType()==RrCommitteeCharterVersion.QuorumType.COUNT?BigDecimal.valueOf(attending).compareTo(charter.getQuorumValue())>=0:eligible>0&&BigDecimal.valueOf(attending*100L).divide(BigDecimal.valueOf(eligible),2,RoundingMode.HALF_UP).compareTo(charter.getQuorumValue())>=0;if(!quorum)throw new IllegalStateException("Committee quorum is not met");var outcome=in.outcome();if(outcome==RrDecisionEvent.Outcome.RECOMMEND){var category=categories.findByIdAndAgencyId(value.getCategoryVersionId(),a).orElseThrow(()->new ResourceNotFoundException("Award category not found"));if(category.getMinimumScore()!=null&&value.getCalculatedScore().compareTo(category.getMinimumScore())<0)throw new IllegalStateException("Calculated score is below the frozen category minimum");value.recommend(true,eligible,attending,true);}else if(outcome==RrDecisionEvent.Outcome.NOT_RECOMMEND)value.recommend(false,eligible,attending,true);else if(outcome==RrDecisionEvent.Outcome.RETURN||outcome==RrDecisionEvent.Outcome.DISQUALIFY)value.closeDeliberation(outcome==RrDecisionEvent.Outcome.RETURN?RrEvaluationCase.Status.RETURNED:RrEvaluationCase.Status.DISQUALIFIED,eligible,attending,true);else throw new IllegalArgumentException("Unsupported committee outcome");events.save(new RrDecisionEvent(a,id,RrDecisionEvent.Type.COMMITTEE_RECOMMENDATION,outcome,value.getCalculatedScore(),eligible,attending,true,in.reason(),actor,Instant.now()));value=cases.saveAndFlush(value);record(a,"RR_COMMITTEE_RECOMMENDATION",value,null,response(a,value),in.reason(),c);return response(a,value);}
 @Override public CaseResponse decide(String a,String id,DecisionInput in,String actor,String c){var value=entity(a,id);check(value.getVersion(),in.recordVersion());if(assignments.findByAgencyIdAndEvaluationCaseIdOrderByDisplayName(a,id).stream().anyMatch(x->x.getEmployeeNo().equalsIgnoreCase(actor)))throw new AccessDeniedException("Committee evaluators cannot also make the head-of-agency final decision");if(in.outcome()!=RrDecisionEvent.Outcome.APPROVE&&in.outcome()!=RrDecisionEvent.Outcome.DISAPPROVE)throw new IllegalArgumentException("Final outcome must be APPROVE or DISAPPROVE");value.finalDecision(in.outcome()==RrDecisionEvent.Outcome.APPROVE);events.save(new RrDecisionEvent(a,id,RrDecisionEvent.Type.FINAL_DECISION,in.outcome(),value.getCalculatedScore(),value.getEligibleVoters(),value.getAttendingVoters(),value.getQuorumMet(),in.reason(),actor,Instant.now()));value=cases.saveAndFlush(value);record(a,"RR_HEAD_OF_AGENCY_DECISION",value,null,response(a,value),in.reason(),c);return response(a,value);}
 @Override public CaseResponse issue(String a,String id,IssueInput in,String actor,String c){var value=entity(a,id);check(value.getVersion(),in.recordVersion());if(issues.existsByAgencyIdAndEvaluationCaseIdAndStatus(a,id,RrDecisionIssue.Status.OPEN))throw new OptimisticConflictException("An issue is already open");value.requestReconsideration();issues.save(new RrDecisionIssue(a,id,in.grounds(),actor,Instant.now()));value=cases.saveAndFlush(value);record(a,"FILE_RR_RECONSIDERATION",value,null,response(a,value),in.grounds(),c);return response(a,value);}
 @Override public CaseResponse resolveIssue(String a,String caseId,String issueId,ResolveIssueInput in,String actor,String c){var value=entity(a,caseId);var issue=issues.findByIdAndAgencyId(issueId,a).orElseThrow(()->new ResourceNotFoundException("Decision issue not found"));if(!issue.getEvaluationCaseId().equals(caseId))throw new ResourceNotFoundException("Decision issue not found");check(value.getVersion(),in.caseRecordVersion());check(issue.getVersion(),in.issueRecordVersion());if(in.outcome()!=RrDecisionEvent.Outcome.APPROVE&&in.outcome()!=RrDecisionEvent.Outcome.DISAPPROVE)throw new IllegalArgumentException("Resolution outcome must be APPROVE or DISAPPROVE");issue.resolve(in.reason(),actor,Instant.now(),in.dismiss());value.resolveReconsideration(in.outcome()==RrDecisionEvent.Outcome.APPROVE);events.save(new RrDecisionEvent(a,caseId,RrDecisionEvent.Type.RECONSIDERATION_RESOLUTION,in.outcome(),value.getCalculatedScore(),value.getEligibleVoters(),value.getAttendingVoters(),value.getQuorumMet(),in.reason(),actor,Instant.now()));issues.save(issue);value=cases.saveAndFlush(value);record(a,"RESOLVE_RR_RECONSIDERATION",value,null,response(a,value),in.reason(),c);return response(a,value);}
 private List<RrEvaluatorAssignment>activeSubmitted(String a,String id){return assignments.findByAgencyIdAndEvaluationCaseIdOrderByDisplayName(a,id).stream().filter(x->x.isVotingMember()&&x.getStatus()==RrEvaluatorAssignment.Status.SUBMITTED&&!x.isConflictDeclared()).toList();}
 private boolean visible(String a,RrEvaluationCase x,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return true;return assignments.findByAgencyIdAndEvaluationCaseIdOrderByDisplayName(a,x.getId()).stream().anyMatch(y->y.getEmployeeNo().equalsIgnoreCase(actor));}
 private void access(String a,RrEvaluationCase x,String actor,PermissionDataScope scope){if(!visible(a,x,actor,scope))throw new AccessDeniedException("Evaluation case is outside the assigned scope");}
 private boolean isNominee(String a,RrNomination n,String employee){return employee.equalsIgnoreCase(Objects.toString(n.getIndividualEmployeeNo(),""))||nominationMembers.findByAgencyIdAndNominationIdOrderByDisplayOrderAsc(a,n.getId()).stream().anyMatch(x->x.getEmployeeNo().equalsIgnoreCase(employee));}
 private String fingerprint(RrCommitteeCharterVersion c,List<RrCommitteeMember> roster){try{return hex(json.writeValueAsString(Map.of("id",c.getId(),"version",c.getDefinitionVersion(),"rosterRevision",c.getRosterRevision(),"members",roster.stream().map(x->x.getEmployeeNo()+":"+x.getMemberRole()+":"+x.isVotingMember()).toList())).getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException("Committee fingerprint could not be calculated",e);}}
 private static String hex(byte[] x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x));}catch(Exception e){throw new IllegalStateException(e);}}
 private RrEvaluationCase entity(String a,String id){return cases.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Evaluation case not found"));}private RrNomination nomination(String a,String id){return nominations.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Nomination not found"));}private RrEvaluatorAssignment assignment(String a,String id){return assignments.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Evaluator assignment not found"));}private static void belong(RrEvaluationCase c,RrEvaluatorAssignment a){if(!a.getEvaluationCaseId().equals(c.getId()))throw new ResourceNotFoundException("Evaluator assignment not found");}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
 private CaseResponse response(String a,RrEvaluationCase x){return new CaseResponse(x.getId(),x.getVersion(),x.getNominationId(),x.getCycleId(),x.getCategoryVersionId(),x.getCharterVersionId(),x.getCharterDefinitionVersion(),x.getCharterFingerprint(),x.getStatus().name(),x.getEligibilitySummary(),x.getEligibilityDecidedBy(),x.getEligibilityDecidedAt(),x.getCalculatedScore(),x.getEligibleVoters(),x.getAttendingVoters(),x.getQuorumMet(),findings.findByAgencyIdAndEvaluationCaseIdOrderByRuleCode(a,x.getId()).stream().map(y->new FindingResponse(y.getId(),y.getRuleCode(),y.getRuleLabel(),y.getOutcome().name(),y.getRationale())).toList(),assignments.findByAgencyIdAndEvaluationCaseIdOrderByDisplayName(a,x.getId()).stream().map(y->new AssignmentResponse(y.getId(),y.getVersion(),y.getEmployeeNo(),y.getDisplayName(),y.getPositionTitle(),y.getMemberRole(),y.isVotingMember(),y.getStatus().name(),y.isConflictDeclared(),y.getConflictReason(),y.getReplacementAssignmentId(),y.isAttending(),y.getTotalScore(),y.getSubmittedAt(),ratings.findByAgencyIdAndAssignmentIdOrderByCriterionCode(a,y.getId()).stream().map(z->new RatingResponse(z.getId(),z.getCriterionId(),z.getCriterionCode(),z.getWeightPercent(),z.getMaximumScore(),z.getRawScore(),z.getWeightedScore(),z.getComments())).toList())).toList(),events.findByAgencyIdAndEvaluationCaseIdOrderByDecidedAt(a,x.getId()).stream().map(y->new EventResponse(y.getId(),y.getEventType().name(),y.getOutcome().name(),y.getCalculatedScore(),y.getEligibleVoters(),y.getAttendingVoters(),y.getQuorumMet(),y.getReason(),y.getDecidedBy(),y.getDecidedAt())).toList(),issues.findByAgencyIdAndEvaluationCaseIdOrderByFiledAt(a,x.getId()).stream().map(y->new IssueResponse(y.getId(),y.getVersion(),y.getGrounds(),y.getStatus().name(),y.getFiledBy(),y.getFiledAt(),y.getResolutionReason(),y.getResolvedBy(),y.getResolvedAt())).toList());}
 private void record(String a,String action,com.primehr.rsp.domain.RspAuditedEntity value,Object before,Object after,String reason,String c){audit.record(a,action,value.getClass().getSimpleName(),value.getId(),null,value.getVersion(),before,after,reason,c);}
}
